#!/bin/sh
# Run every tests/programs/*.ts with rts and compare stdout to the .out file
# (generated by Node: tests/run.sh --bless).
cd "$(dirname "$0")/.." || exit 1
BIN=${RTS_BIN:-target/release/rts}
pass=0; fail=0; failed=""
for f in tests/programs/*.ts; do
  exp="${f%.ts}.out"
  if [ "$1" = "--bless" ] || [ ! -f "$exp" ]; then
    node --experimental-transform-types --no-warnings "$f" > "$exp" 2>/dev/null
  fi
  if "$BIN" "$f" > /tmp/rts_test_out.txt 2>/tmp/rts_test_err.txt && cmp -s /tmp/rts_test_out.txt "$exp"; then
    pass=$((pass+1))
  else
    fail=$((fail+1)); failed="$failed $f"
    if [ -n "$VERBOSE" ]; then
      echo "--- FAIL $f"; diff /tmp/rts_test_out.txt "$exp" | head -20; head -5 /tmp/rts_test_err.txt
    fi
  fi
done
# rts-specific behaviour: expected output is checked in by hand.
for f in tests/rts/*.ts; do
  exp="${f%.ts}.out"
  if "$BIN" "$f" > /tmp/rts_test_out.txt 2>/tmp/rts_test_err.txt; cmp -s /tmp/rts_test_out.txt "$exp"; then
    pass=$((pass+1))
  else
    fail=$((fail+1)); failed="$failed $f"
    if [ -n "$VERBOSE" ]; then
      echo "--- FAIL $f"; diff /tmp/rts_test_out.txt "$exp" | head -20; head -5 /tmp/rts_test_err.txt
    fi
  fi
done
echo "passed $pass, failed $fail"
[ $fail -eq 0 ] || { echo "failed:$failed"; exit 1; }
